using System;

namespace StdbModule;

public static partial class EnglishQuotes
{
    public static class TheodoreRoosevelt
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "Speak softly and carry a big stick; you will go far.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "Hit the line hard; don't foul and don't shirk, but hit the line hard!", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "The light has gone out of my life.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "No candid observer will deny that whatever of good there may be in our American civilization is the product of Christianity.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "Of recent years... representative government all over the world has been threatened with a growing paralysis. Legislative bodies have tended more and more to become wholly inefficient for the purposes of legislation. The prime feature in causing this unhealthy growth has been the discovery by minorities that under the old rules of parliamentary procedure they could put a complete stop to all legislative action... If the minority is as powerful as the majority there is no use of having political contests at all, for there is no use in having a majority.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "We cannot afford merely to sit down and deplore the evils of city life as inevitable, when cities are constantly growing, both absolutely and relatively. We must set ourselves vigorously about the task of improving them; and this task is now well begun.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "A perfectly stupid race can never rise to a very high plane; the negro, for instance, has been kept down as much by lack of intellectual development as by anything else; but the prime factor in the preservation of a race is its power to attain a high degree of social efficiency. Love of order, ability to fight well and breed well, capacity to subordinate the interests of the individual to the interests of the community, these and similar rather humdrum qualities go to make up the sum of social efficiency. The race that has them is sure to overturn the race whose members have brilliant intellects, but who are cold and selfish and timid, who do not breed well or fight well, and who are not capable of disinterested love of the community. In other words, character is far more important than intellect to the race as to the individual. We need intellect, and there is no reason why we should not have it together with character; but if we must choose between the two we choose character without a moment's hesitation.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "There is much talk about \"jingoism\". If by \"jingoism\" they mean a policy in pursuance of which Americans will with resolution and common sense insist upon our rights being respected by foreign powers, then we are \"jingoes\".", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "The worst lesson that can be taught a man is to rely upon others and to whine over his sufferings.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "It is both foolish and wicked to teach the average man who is not well off that some wrong or injustice has been done him, and that he should hope for redress elsewhere than in his own industry, honesty and intelligence.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "Is America a weakling, to shrink from the work of the great world powers? No! The young giant of the West stands on a continent and clasps the crest of an ocean in either hand. Our nation, glorious in youth and strength, looks into the future with eager eyes and rejoices as a strong man to run a race.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "To sit home, read one's favorite paper, and scoff at the misdeeds of the men who do things is easy, but it is markedly ineffective. It is what evil men count upon the good men's doing.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "To borrow a simile from the football field, we believe that men must play fair, but that there must be no shirking, and that the success can only come to the player who hits the line hard.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "If we lose the virile, manly qualities, and sink into a nation of mere hucksters, putting gain over national honor, and subordinating everything to mere ease of life, then we shall indeed reach a condition worse than that of the ancient civilizations in the years of their decay.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "Every man among us is more fit to meet the duties and responsibilities of citizenship because of the perils over which, in the past, the nation has triumphed; because of the blood and sweat and tears, the labor and the anguish, through which, in the days that have gone, our forefathers moved on to triumph.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "Greatness means strife for nation and man alike. A soft, easy life is not worth living, if it impairs the fibre of brain and heart and muscle. We must dare to be great; and we must realize that greatness is the fruit of toil and sacrifice and high courage... We are face to face with our destiny and we must meet it with a high and resolute courage. For us is the life of action, of strenuous performance of duty; let us live in the harness, striving mightily; let us rather run the risk of wearing out than rusting out.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "Don't let anyone impose on you. Don't be quarrelsome, but stand up for your rights. If you've got to fight, fight hard and well. To my mind, a coward is the only thing meaner than a liar.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "There are two things that I want you to make up your minds to: first, that you are going to have a good time as long as you live – I have no use for the sour-faced man – and next, that you are going to do something worthwhile, that you are going to work hard and do the things you set out to do.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "The government is us; we are the government, you and I.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "Death is always and under all circumstances a tragedy, for if it is not, then it means that life itself has become one.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "It is a dreadful thing to come into the Presidency in this way; but it would be far worse to be morbid about it. Here is the task, and I have got to do it to the best of my ability.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "I can be President of the United States, or I can control Alice. I cannot possibly do both.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "Probably the greatest harm done by vast wealth is the harm that we of moderate means do ourselves when we let the vices of envy and hatred enter deep into our own natures. But there is another harm; and it is evident that we should try to do away with that. The great corporations which we have grown to speak of rather loosely as trusts are the creatures of the State, and the State not only has the right to control them, but it is duty bound to control them wherever the need of such control is shown.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "I don't pity any man who does hard work worth doing. I admire him. I pity the creature who does not work, at whichever end of the social scale he may regard himself as being.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "I cannot consent to take the position that the door of hope — the door of opportunity — is to be shut upon any man, no matter how worthy, purely upon the grounds of race or color. Such an attitude would, according to my convictions, be fundamentally wrong.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "The first requisite of a good citizen in this Republic of ours is that he shall be able and willing to pull his weight; that he shall not be a mere passenger, but shall do his share in the work that each generation of us finds ready to hand; and, furthermore, that in doing his work he shall show, not only the capacity for sturdy self-help, but also self-respecting regard for the rights of others.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "Our aim is not to do away with corporations; on the contrary, these big aggregations are an inevitable development of modern industrialism, and the effort to destroy them would be futile unless accomplished in ways that would work the utmost mischief to the entire body politic. We can do nothing of good in the way of regulating and supervising these corporations until we fix clearly in our minds that we are not attacking the corporations, but endeavoring to do away with any evil in them. We are not hostile to them; we are merely determined that they shall be so handled as to subserve the public good. We draw the line against misconduct, not against wealth.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "Let us speak courteously, deal fairly, and keep ourselves armed and ready.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "A man who is good enough to shed his blood for his country is good enough to be given a square deal afterwards. More than that no man is entitled to, and less than that no man shall have.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "It is no use to preach to [children] if you do not act decently yourself.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "There are good men and bad men of all nationalities, creeds and colors; and if this world of ours is ever to become what we hope some day it may become, it must be by the general recognition that the man's heart and soul, the man's worth and actions, determine his standing.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "No man is above the law and no man is below it; nor do we ask any man's permission when we require him to obey it. Obedience to the law is demanded as a right; not asked as a favor.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "The only man who makes no mistakes is the man who never does anything.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "We face the future with our past and our present as guarantors of our promises; and we are content to stand or to fall by the record which we have made and are making.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "Any country whose people conduct themselves well can count upon our hearty friendship. If a nation shows that it knows how to act with reasonable efficiency and decency in social and political matters, if it keeps order and pays its obligations, it need fear no interference from the United States. Chronic wrongdoing, or an impotence which results in a general loosening of the ties of civilized society, may in America, as elsewhere, ultimately require intervention by some civilized nation, and in the Americas the adherence of the United States to the Monroe Doctrine may force the United States, however reluctantly, in flagrant cases of such wrongdoing or impotence, to the exercise of an international police power.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "It is enough to give any one a sense of sardonic amusement to see the way in which the people generally, not only in my own country but elsewhere, gauge the work purely by the fact that it succeeded. If I had not brought about peace I should have been laughed at and condemned. Now I am over-praised. I am credited with being extremely longheaded, etc. As a matter of fact I took the position I finally did not of my own volition but because events so shaped themselves that I would have felt as if I was flinching from a plain duty if I had acted otherwise.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "It is a very poor thing, whether for nations or individuals, to advance the history of great deeds done in the past as an excuse for doing poorly in the present; but it is an excellent thing to study the history of the great deeds of the past, and of the great men who did them, with an earnest desire to profit thereby so as to render better service in the present. In their essentials, the men of the present day are much like the men of the past, and the live issues of the present can be faced to better advantage by men who have in good faith studied how the leaders of the nation faced the dead issues of the past. Such a study of Lincoln's life will enable us to avoid the twin gulfs of immorality and inefficiency—the gulfs which always lie one on each side of the careers alike of man and of nation. It helps nothing to have avoided one if shipwreck is encountered in the other. The fanatic, the well-meaning moralist of unbalanced mind, the parlor critic who condemns others but has no power himself to do good and but little power to do ill—all these were as alien to Lincoln as the vicious and unpatriotic themselves. His life teaches our people that they must act with wisdom, because otherwise adherence to right will be mere sound and fury without substance; and that they must also act high-mindedly, or else what seems to be wisdom will in the end turn out to be the most destructive kind of folly.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "This country has nothing to fear from the crooked man who fails. We put him in jail. It is the crooked man who succeeds who is a threat to this country.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "Men with the muckrake are often indispensable to the well-being of society, but only if they know when to stop raking the muck, and to look upward to the celestial crown above them. ... If they gradually grow to feel that the whole world is nothing but muck their power of usefulness is gone.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "Malefactors of great wealth.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "To waste, to destroy, our natural resources, to skin and exhaust the land instead of using it so as to increase its usefulness, will result in undermining in the days of our children the very prosperity which we ought by right to hand down to them amplified and developed.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "Anybody who says saccharin is injurious to health is an idiot.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "The demand for a statement of a candidate's religious belief can have no meaning except that there may be discrimination for or against him because of that belief. Discrimination against the holder of one faith means retaliatory discrimination against men of other faiths. The inevitable result of entering upon such a practice would be an abandonment of our real freedom of conscience and a reversion to the dreadful conditions of religious dissension which in so many lands have proved fatal to true liberty, to true religion, and to all advance in civilization.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "To discriminate against a thoroughly upright citizen because he belongs to some particular church, or because, like Abraham Lincoln, he has not avowed his allegiance to any church, is an outrage against that liberty of conscience which is one of the foundations of American life. You are entitled to know whether a man seeking your suffrages is a man of clean and upright life, honorable in all of his dealings with his fellows, and fit by qualification and purpose to do well in the great office for which he is a candidate; but you are not entitled to know matters which lie purely between himself and his Maker. If it is proper or legitimate to oppose a man for being a Unitarian, as was John Quincy Adams, for instance, as is the Rev. Edward Everett Hale, at the present moment Chaplain of the Senate, and an American of whose life all good Americans are proud then it would be equally proper to support or oppose a man because of his views on justification by faith, or the method of administering the sacrament, or the gospel of salvation by works. If you once enter on such a career there is absolutely no limit at which you can legitimately stop.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "To permit every lawless capitalist, every law-defying corporation, to take any action, no matter how iniquitous, in the effort to secure an improper profit and to build up privilege, would be ruinous to the Republic and would mark the abandonment of the effort to secure in the industrial world the spirit of democratic fair dealing.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "I wish to preach, not the doctrine of ignoble ease, but the doctrine of the strenuous life, the life of toil and effort, of labor and strife; to preach that highest form of success which comes, not to the man who desires mere easy peace, but to the man who does not shrink from danger, from hardship, or from bitter toil, and who out of these wins the splendid ultimate triumph.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "A life of slothful ease, a life of that peace which springs merely from lack either of desire or of power to strive after great things, is as little worthy of a nation as of an individual. [...] If you are rich and are worth your salt, you will teach your sons that though they may have leisure, it is not to be spent in idleness; for wisely used leisure merely means that those who possess it, being free from the necessity of working for their livelihood, are all the more bound to carry on some kind of non-remunerative work in science, in letters, in art, in exploration, in historical research—work of the type we most need in this country, the successful carrying out of which reflects most honor upon the nation. We do not admire the man of timid peace. We admire the man who embodies victorious effort; the man who never wrongs his neighbor, who is prompt to help a friend, but who has those virile qualities necessary to win in the stern strife of actual life. It is hard to fail, but it is worse never to have tried to succeed. In this life we get nothing save by effort. Freedom from effort in the present merely means that there has been stored up effort in the past. A man can be freed from the necessity of work only by the fact that he or his fathers before him have worked to good purpose. If the freedom thus purchased is used aright, and the man still does actual work, though of a different kind, whether as a writer or a general, whether in the field of politics or in the field of exploration and adventure, he shows he deserves his good fortune. But if he treats this period of freedom from the need of actual labor as a period, not of preparation, but of mere enjoyment, even though perhaps not of vicious enjoyment, he shows that he is simply a cumberer of the earth's surface, and he surely unfits himself to hold his own with his fellows if the need to do so should again arise.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "A mere life of ease is not in the end a very satisfactory life, and, above all, it is a life which ultimately unfits those who follow it for serious work in the world. In the last analysis a healthy state can exist only when the men and women who make it up lead clean, vigorous, healthy lives; when the children are so trained that they shall endeavor, not to shirk difficulties, but to overcome them; not to seek ease, but to know how to wrest triumph from toil and risk.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "Far better it is to dare mighty things, to win glorious triumphs, even though checkered by failure, than to rank with those poor spirits who neither enjoy much nor suffer much, because they live in that grey twilight that knows neither victory nor defeat.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "We cannot, if we would, play the part of China, and be content to rot by inches in ignoble ease within our borders, taking no interest in what goes on beyond them, sunk in a scrambling commercialism; heedless of the higher life, the life of aspiration, of toil and risk, busying ourselves only with the wants of our bodies for the day, until suddenly we should find, beyond a shadow of question, what China has already found, that in this world the nation that has trained itself to a career of unwarlike and isolated ease is bound, in the end, to go down before other nations which have not lost the manly and adventurous qualities. If we are to be a really great people, we must strive in good faith to play a great part in the world.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "We cannot avoid meeting great issues. All that we can determine for ourselves is whether we shall meet them well or ill.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "We have a given problem to solve. If we undertake the solution, there is, of course, always danger that we may not solve it aright; but to refuse to undertake the solution simply renders it certain that we cannot possibly solve it aright.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "No country can long endure if its foundations are not laid deep in the material prosperity which comes from thrift, from business energy and enterprise, from hard, unsparing effort in the fields of industrial activity; but neither was any nation ever yet truly great if it relied upon material prosperity alone. All honor must be paid to the architects of our material prosperity, to the great captains of industry who have built our factories and our railroads, to the strong men who toil for wealth with brain or hand; for great is the debt of the nation to these and their kind. But our debt is yet greater to the men whose highest type is to be found in a statesman like Lincoln, a soldier like Grant. They showed by their lives that they recognized the law of work, the law of strife; they toiled to win a competence for themselves and those dependent upon them; but they recognized that there were yet other and even loftier duties—duties to the nation and duties to the race. We cannot sit huddled within our own borders and avow ourselves merely an assemblage of well-to-do hucksters who care nothing for what happens beyond. Such a policy would defeat even its own end; for as the nations grow to have ever wider and wider interests, and are brought into closer and closer contact, if we are to hold our own in the struggle for naval and commercial supremacy, we must build up our power without our own borders. We must build the Isthmian Canal, and we must grasp the points of vantage which will enable us to have our say in deciding the destiny of the oceans of the East and the West.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "We must demand the highest order of integrity and ability in our public men who are to grapple with these new problems. We must hold to a rigid accountability those public servants who show unfaithfulness to the interests of the nation or inability to rise to the high level of the new demands upon our strength and our resources. Of course we must remember not to judge any public servant by any one act, and especially should we beware of attacking the men who are merely the occasions and not the causes of disaster.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "A man's first duty is to his own home, but he is not thereby excused from doing his duty to the State; for if he fails in this second duty it is under the penalty of ceasing to be a freeman. In the same way, while a nation's first duty is within its own borders, it is not thereby absolved from facing its duties in the world as a whole; and if it refuses to do so, it merely forfeits its right to struggle for a place among the peoples that shape the destiny of mankind.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "If we stand idly by, if we seek merely swollen, slothful ease and ignoble peace, if we shrink from the hard contests where men must win at hazard of their lives and at the risk of all they hold dear, then the bolder and stronger peoples will pass us by, and will win for themselves the domination of the world. Let us therefore boldly face the life of strife, resolute to do our duty well and manfully; resolute to uphold righteousness by deed and by word; resolute to be both honest and brave, to serve high ideals, yet to use practical methods. Above all, let us shrink from no strife, moral or physical, within or without the nation, provided we are certain that the strife is justified, for it is only through strife, through hard and dangerous endeavor, that we shall ultimately win the goal of true national greatness.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "Our country has been populated by pioneers, and therefore it has in it more energy, more enterprise, more expansive power than any other in the wide world. [...] They have shown the qualities of daring, endurance, and far-sightedness, of eager desire for victory and stubborn refusal to accept defeat, which go to make up the essential manliness of the American character. Above all, they have recognized in practical form the fundamental law of success in American life—the law of worthy work, the law of high, resolute endeavor. We have but little room among our people for the timid, the irresolute, and the idle; and it is no less true that there is scant room in the world at large for the nation with mighty thews that dares not to be great.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "Throughout our history the success of the homemaker has been but another name for the up-building of the nation.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "Poverty is a bitter thing; but it is not as bitter as the existence of restless vacuity and physical, moral, and intellectual flabbiness, to which those doom themselves who elect to spend all their years in that vainest of all vain pursuits—the pursuit of mere pleasure as a sufficient end in itself.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "The willfully idle man, like the willfully barren woman, has no place in a sane, healthy, and vigorous community. Moreover, the gross and hideous selfishness for which each stands defeats even its own miserable aims. Exactly as infinitely the happiest woman is she who has borne and brought up many healthy children, so infinitely the happiest man is he who has toiled hard and successfully in his life-work. The work may be done in a thousand different ways —with the brain or the hands, in the study, the field, or the workshop—if it is honest work, honestly done and well worth doing, that is all we have a right to ask. Every father and mother here, if they are wise, will bring up their children not to shirk difficulties, but to meet them and overcome them; not to strive after a life of ignoble ease, but to strive to do their duty, first to themselves and their families, and then to the whole state; and this duty must inevitably take the shape of work in some form or other.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "You, the sons of the pioneers, if you are true to your ancestry, must make your lives as worthy as they made theirs. They sought for true success, and therefore they did not seek ease. They knew that success comes only to those who lead the life of endeavor.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "It seems to me that the simple acceptance of this fundamental fact of American life, this acknowledgment that the law of work is the fundamental law of our being, will help us to start aright in facing not a few of the problems that confront us from without and from within. As regards internal affairs, it should teach us the prime need of remembering that, after all has been said and done, the chief factor in any man's success or failure must be his own character—that is, the sum of his common sense, his courage, his virile energy and capacity. Nothing can take the place of this individual factor.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "Besides each one of us working individually, all of us have got to work together. We cannot possibly do our best work as a nation unless all of us know how to act in combination as well as how to act each individually for himself. The acting in combination can take many forms, but of course its most effective form must be when it comes in the shape of law —that is, of action by the community as a whole through the lawmaking body.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "But it is not possible ever to insure prosperity merely by law. Something for good can be done by law, and a bad law can do an infinity of mischief; but, after all, the best law can only prevent wrong and injustice, and give to the thrifty, the farseeing, and the hard-working a chance to exercise to best advantage their special and peculiar abilities.", Author = "Theodore Roosevelt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Theodore_Roosevelt", Text = "No hard-and-fast rule can be laid down as to where our legislation shall stop in interfering between man and man, between interest and interest. All that can be said is that it is highly undesirable, on the one hand, to weaken individual initiative, and, on the other hand, that in a constantly increasing number of cases we shall find it necessary in the future to shackle cunning as in the past we have shackled force. It is not only highly desirable but necessary that there should be legislation which shall carefully shield the interests of wage-workers, and which shall discriminate in favor of the honest and humane employer by removing the disadvantage under which he stands when compared with unscrupulous competitors who have no conscience and will do right only under fear of punishment. Nor can legislation stop only with what are termed labor questions. The vast individual and corporate fortunes, the vast combinations of capital, which have marked the development of our industrial system create new conditions, and necessitate a change from the old attitude of the state and the nation toward property.", Author = "Theodore Roosevelt" },
        };
    }
}